contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take a depositAmount to deposit into C so this contract has a positive credit,
    // then call withdrawAll and assert the exact relationship when it succeeds.
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // record C's balance and this contract's observed credit (via deposit/withdraw observable effects)
        uint cBalanceBefore = address(c).balance;

        // deposit to create a credit for this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // read balances after deposit
        uint cBalanceAfterDeposit = address(c).balance;

        // determine whether withdrawAll reverts
        bool withdrewReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        uint cBalanceAfterWithdraw = address(c).balance;

        // If withdrawAll did not revert, then the caller's recorded credit should be zero
        // and C's balance should have decreased by exactly the recorded prior credit (which is the deposited amount).
        // We cannot read the private mapping directly, but since we deposited depositAmount just before,
        // the prior credit for this caller (our contract) is equal to depositAmount (no other calls modify it in-between).
        // Thus when withdrawAll succeeds, C's balance must have decreased by exactly depositAmount.
        assert(withdrewReverted || (cBalanceAfterDeposit == cBalanceAfterWithdraw + depositAmount));
    }

    // allow receiving Ether when C sends funds back on successful withdraw
    receive() external payable {}
}

